s('2:30 AM','ELI','tunnel','night',"The old train tunnel. One flashlight. Two idiots.", a=['hero@420^:flash','ben@300'], cone=1, sfx=['drip'])
s('2:45 AM','ELI','tunnel','night',"We could hear them breathing in the dark. So we did not run. Running is loud.", a=['hero@300>520^:flash','ben@180>400'], cone=1, eyes=1, sfx=['moans'])
s('3:10 AM','BEN','tunnel','night',"Are we there yet?", a=['hero@520^:flash','ben@400'], talk='ben', cone=1, eyes=1)
