s('3:40 AM','ELI','tunnel','night',"Halfway through, the flashlight died.", a=['hero@520!','ben@400!'], eyes=1, dark=.8, sfx=['buzz'])
s('5:30 AM','ELI','tunnel','night',"So we held on to the wall, and walked. For two hours. In the dark. I have never been so happy to smell fish.", a=['hero@300>640','ben@180>520'], eyes=1, dark=.78, cam='in')
s('5:50 AM','ELI','harbor','dawn',"We came out at the harbor, just as the sun came up.", a=['hero@100>420','ben@0>300'], sfx=['boathorn'], pre=1.3)
s('5:51 AM','ELI','harbor','dawn',"One boat was left. And the gate was closing.", a=['hero@420!','ben@300!'], cam='in')
s('5:51 AM','HERO','harbor','dawn',"Wait! Wait! Two more!", a=['hero@300>>560^','ben@180>>440^'], talk='hero', sfx=['steps'], shake=1)
s('5:51 AM','SOLDIER','harbor','dawn',"Two survivors! Hold the gate! Move, move, move!", a=['hero@520^','ben@400^','soldier@900<^'], talk='soldier', gate=1, sfx=['gate'])
s('5:52 AM','ELI','harbor','dawn',"We made it on with nine seconds left. I counted.", a=['hero@560>>760','ben@440>>640','soldier@920<'], gate=2)
