s('5:53 AM','ELI','harbor','dawn',"My dad was standing right there. He looked at me. Then he looked at the colander.", a=['civ@880<','hero@720','ben@600'], gate=2, cam='in')
s('5:53 AM','DAD','harbor','dawn',"Son. What is on your head?", a=['civ@880<','hero@720','ben@600'], talk='civ', gate=2)
